import {Effect} from "effect";
export const check = Effect.gen(function* () {
const path = yield* Path.Path;
const input = yield* path.fromFileUrl(new URL("../../cloudflare/src/Workers/SqlMigrationsApply.ts", import.meta.url));
const {rolldown} = yield* Effect.promise(() => import("rolldown"));
return yield* Effect.promise(() => rolldown({input,plugins:[{name:"test-oracle"}]}));
});

